<?php
declare(strict_types=1);
namespace Nexus\Features\Prestamo\Infrastructure;
use Nexus\Features\Prestamo\Domain\PrestamoRepository;use Nexus\Shared\Domain\ValueObject\Cedula;
final class PdoPrestamoRepository implements PrestamoRepository
{
    private \PDO $pdo;public function __construct(\PDO $p){$this->pdo=$p;}
    public function listar(Cedula $u,bool $g):array{$sql="SELECT p.id_prestamo,p.categoria,p.estado,p.fecha_solicitado,p.fecha_devolucion,p.fecha_devolucion_real,p.recursos_solicitados,p.jornada,p.lugar_entrega,p.descripcion,p.comentario_resolucion,p.cedula,u.nombre,u.apellido,e.id_equipo,e.nombre_equipo,e.cantidad_del_equipo,COALESCE((SELECT SUM(CAST(SUBSTRING_INDEX(px.recursos_solicitados,' ',1) AS UNSIGNED)) FROM PRESTAMO px WHERE px.id_equipo=e.id_equipo AND px.esta_activo=1 AND px.estado IN ('Solicitado','Activo')),0) cantidad_reservada,GREATEST(e.cantidad_del_equipo-COALESCE((SELECT SUM(CAST(SUBSTRING_INDEX(py.recursos_solicitados,' ',1) AS UNSIGNED)) FROM PRESTAMO py WHERE py.id_equipo=e.id_equipo AND py.esta_activo=1 AND py.estado IN ('Solicitado','Activo')),0),0) cantidad_disponible FROM PRESTAMO p INNER JOIN USUARIO u ON u.cedula=p.cedula INNER JOIN EQUIPO e ON e.id_equipo=p.id_equipo WHERE p.esta_activo=1";$p=[];if(!$g){$sql.=' AND p.cedula=?';$p[]=$u->value();}$sql.=' ORDER BY p.id_prestamo DESC';$q=$this->pdo->prepare($sql);$q->execute($p);return $q->fetchAll(\PDO::FETCH_ASSOC);}
    public function diasMaximos():int{$v=$this->pdo->query("SELECT valor FROM CONFIGURACION_SISTEMA WHERE clave='dias_maximos_prestamo'")->fetchColumn();return (int)($v?:30);}
    public function crear(array $d,Cedula $u):array{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("INSERT INTO PRESTAMO(categoria,estado,fecha_solicitado,fecha_devolucion,recursos_solicitados,jornada,lugar_entrega,descripcion,cedula,id_equipo) VALUES(?,'Solicitado',CURDATE(),?,?,?,?,?,?,?)");$v=$this->pdo->prepare('INSERT INTO SOLICITA_PRESTAMO(cedula,id_prestamo) VALUES(?,?)');$equipo=$this->pdo->prepare("SELECT categoria_equipo,cantidad_del_equipo,esta_activo,estado_equipo FROM EQUIPO WHERE id_equipo=? FOR UPDATE");$ocupados=$this->pdo->prepare("SELECT COALESCE(SUM(CAST(SUBSTRING_INDEX(recursos_solicitados,' ',1) AS UNSIGNED)),0) FROM PRESTAMO WHERE id_equipo=? AND esta_activo=1 AND estado IN ('Solicitado','Activo')");$ids=[];foreach($d['recursos'] as $r){$equipo->execute([$r['idEquipo']]);$inventario=$equipo->fetch(\PDO::FETCH_ASSOC);if(!$inventario||(int)$inventario['esta_activo']!==1||in_array($inventario['estado_equipo'],['Baja','Mantenimiento'],true))throw new \Nexus\Shared\DomainException('El equipo seleccionado no esta disponible.',409);$categoria=($r['categoria']??'')!==''?$r['categoria']:($d['categoria']!==''?$d['categoria']:(string)$inventario['categoria_equipo']);if($this->normalizarCategoria($inventario['categoria_equipo'])!==$this->normalizarCategoria($categoria))throw new \Nexus\Shared\DomainException('El equipo seleccionado no pertenece a la categoria elegida.',409);preg_match('/^(\d+)\s/u',$r['descripcion'],$m);$solicitados=(int)($m[1]??0);$ocupados->execute([$r['idEquipo']]);$disponibles=(int)$inventario['cantidad_del_equipo']-(int)$ocupados->fetchColumn();if($solicitados<1||$solicitados>$disponibles)throw new \Nexus\Shared\DomainException('No hay suficientes equipos disponibles para la cantidad solicitada.',409);$q->execute([$categoria,$d['fecha'],$r['descripcion'],$d['jornada'],$d['ubicacion'],$d['detalle'],$u->value(),$r['idEquipo']]);$id=(int)$this->pdo->lastInsertId();$v->execute([$u->value(),$id]);$this->historial($id,'Solicitado','Solicitud creada por '.$u->value().'.');$ids[]=$id;}$this->pdo->commit();return $ids;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function baja(int $id,Cedula $responsable):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('SELECT estado FROM PRESTAMO WHERE id_prestamo=? AND esta_activo=1 FOR UPDATE');$q->execute([$id]);$estado=$q->fetchColumn();if($estado===false){$this->pdo->rollBack();return false;}$q=$this->pdo->prepare("UPDATE PRESTAMO SET esta_activo=0,estado=CASE WHEN estado='Devuelto' THEN estado ELSE 'Cancelado' END WHERE id_prestamo=?");$q->execute([$id]);$final=$estado==='Devuelto'?'Devuelto':'Cancelado';$this->historial($id,$final,'Baja administrativa realizada por '.$responsable->value().'.');$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    public function comentar(int $id,string $c,Cedula $responsable):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare("UPDATE PRESTAMO SET comentario_resolucion=? WHERE id_prestamo=? AND esta_activo=1 AND estado IN ('Activo','Devuelto','Cancelado') AND (comentario_resolucion IS NULL OR TRIM(comentario_resolucion)='')");$q->execute([$c,$id]);if($q->rowCount()!==1){$this->pdo->rollBack();return false;}$e=$this->pdo->prepare('SELECT estado FROM PRESTAMO WHERE id_prestamo=?');$e->execute([$id]);$this->historial($id,(string)$e->fetchColumn(),'Comentario agregado por '.$responsable->value().': '.$c);$this->pdo->commit();return true;}catch(\Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}}
    private function normalizarCategoria(string $valor):string{$valor=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$valor)?:$valor;$valor=strtolower($valor);$valor=preg_replace('/[^a-z0-9]+/',' ',trim($valor))??$valor;$valor=preg_replace('/\b([a-z0-9]{3,})s\b/','$1',$valor)??$valor;return trim($valor);}
    public function cambiarEstado(int $id,string $e,Cedula $responsable,string $observacion=''):bool{$this->pdo->beginTransaction();try{$q=$this->pdo->prepare('SELECT p.estado,p.id_equipo,e.cantidad_del_equipo,e.esta_activo,e.estado_equipo FROM PRESTAMO p INNER JOIN EQUIPO e ON e.id_equipo=p.id_equipo WHERE p.id_prestamo=? AND p.esta_activo=1 FOR UPDATE');$q->execute([$id]);$p=$q->fetch(\PDO::FETCH_ASSOC);if(!$p){$this->pdo->rollBack();return false;}$permitidas=['Solicitado'=>['Activo','Cancelado'],'Activo'=>['Devuelto'],'Devuelto'=>[],'Cancelado'=>[]];if(!in_array($e,$permitidas[$p['estado']]??[],true))throw new \Nexus\Shared\DomainException('La transicion de '.$p['estado'].' a '.$e.' no esta permitida.',409);if($e==='Activo'){if((int)$p['esta_activo']!==1||in_array($p['estado_equipo'],['Baja','Mantenimiento'],true))throw new \Nexus\Shared\DomainException('El equipo ya no esta habilitado para aprobar el prestamo.',409);$r=$this->pdo->prepare("SELECT COALESCE(SUM(CAST(SUBSTRING_INDEX(recursos_solicitados,' ',1) AS UNSIGNED)),0) FROM PRESTAMO WHERE id_equipo=? AND esta_activo=1 AND estado IN ('Solicitado','Activo')");$r->execute([$p['id_equipo']]);if((int)$r->fetchColumn()>(int)$p['cantidad_del_equipo'])throw new \Nexus\Shared\DomainException('No hay stock suficiente para aprobar el prestamo.',409);}$q=$this->pdo->prepare("UPDATE PRESTAMO SET estado=?,fecha_devolucion_real=CASE WHEN ?='Devuelto' THEN NOW() ELSE fecha_devolucion_real END WHERE id_prestamo=?");$q->execute([$e,$e,$id]);$texto=$observacion!==''?$observacion:'Cambio de estado realizado por '.$responsable->value().'.';$this->historial($id,$e,$texto);$this->pdo->commit();return true;}catch(\Throwable $x){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $x;}}
    private function historial(int $id,string $estado,string $observacion):void{$q=$this->pdo->prepare('INSERT INTO HISTORIAL_PRESTAMO(estado,observacion,id_prestamo) VALUES(?,?,?)');$q->execute([$estado,$observacion,$id]);}
}
